  1	import {
  2	  OPTION_DEFINITIONS,
  3	  OPTION_LOOKUP,
  4	  formatHelp,
  5	  formatUsage,
  6	} from './spec.mjs';
  7	
  8	const INTEGER_PATTERN = /^[+-]?(?:\d(?:_?\d)*)$/;
  9	const NEGATIVE_NUMBERISH_PATTERN = /^-\d(?:_?\d)*(?:\.\d(?:_?\d)*)?$/;
 10	
 11	export class CliExit extends Error {
 12	  constructor(code, streamName, message) {
 13	    super(message);
 14	    this.code = code;
 15	    this.streamName = streamName;
 16	  }
 17	}
 18	
 19	export function parseCommandLine(argv, programName) {
 20	  const parsed = {};
 21	  const extras = [];
 22	
 23	  for (let index = 0; index < argv.length; index += 1) {
 24	    const token = argv[index];
 25	
 26	    if (token === '-h' || token === '--help') {
 27	      throw new CliExit(0, 'stdout', formatHelp(programName));
 28	    }
 29	
 30	    if (token === '--') {
 31	      extras.push(...argv.slice(index + 1));
 32	      break;
 33	    }
 34	
 35	    if (!token.startsWith('-') || token === '-') {
 36	      extras.push(token);
 37	      continue;
 38	    }
 39	
 40	    if (!token.startsWith('--')) {
 41	      extras.push(token);
 42	      continue;
 43	    }
 44	
 45	    const separatorIndex = token.indexOf('=');
 46	    const optionToken = separatorIndex === -1 ? token : token.slice(0, separatorIndex);
 47	    const definition = OPTION_LOOKUP[optionToken];
 48	
 49	    if (!definition) {
 50	      extras.push(token);
 51	      continue;
 52	    }
 53	
 54	    let rawValue;
 55	
 56	    if (separatorIndex !== -1) {
 57	      rawValue = token.slice(separatorIndex + 1);
 58	    } else {
 59	      const nextToken = argv[index + 1];
 60	
 61	      if (nextToken === undefined || valueWouldBeTreatedAsOption(nextToken, definition.type)) {
 62	        throw usageError(programName, `argument ${optionToken}: expected one argument`);
 63	      }
 64	
 65	      rawValue = nextToken;
 66	      index += 1;
 67	    }
 68	
 69	    parsed[definition.name] = parseValue(optionToken, definition.type, rawValue, programName);
 70	  }
 71	
 72	  if (extras.length > 0) {
 73	    throw usageError(programName, `unrecognized arguments: ${extras.join(' ')}`);
 74	  }
 75	
 76	  const missing = OPTION_DEFINITIONS
 77	    .filter((definition) => !(definition.name in parsed))
 78	    .map((definition) => `--${definition.name}`);
 79	
 80	  if (missing.length > 0) {
 81	    throw usageError(programName, `the following arguments are required: ${missing.join(', ')}`);
 82	  }
 83	
 84	  return parsed;
 85	}
 86	
 87	function valueWouldBeTreatedAsOption(token, type) {
 88	  if (token === '-') {
 89	    return false;
 90	  }
 91	
 92	  if (!token.startsWith('-')) {
 93	    return false;
 94	  }
 95	
 96	  if (token.startsWith('--')) {
 97	    return true;
 98	  }
 99	
100	  if (type === 'int') {
101	    return !INTEGER_PATTERN.test(token);
102	  }
103	
104	  return !NEGATIVE_NUMBERISH_PATTERN.test(token);
105	}
106	
107	function parseValue(optionToken, type, rawValue, programName) {
108	  if (type === 'str') {
109	    return rawValue;
110	  }
111	
112	  if (!INTEGER_PATTERN.test(rawValue)) {
113	    throw usageError(programName, `argument ${optionToken}: invalid int value: '${rawValue}'`);
114	  }
115	
116	  return BigInt(rawValue.replaceAll('_', ''));
117	}
118	
119	function usageError(programName, detail) {
120	  return new CliExit(2, 'stderr', `${formatUsage(programName)}
121	${programName}: error: ${detail}
122	`);
123	}

 1	class ConstructBuildError extends Error {
 2	  constructor(message) {
 3	    super(message);
 4	    this.name = 'ConstructBuildError';
 5	  }
 6	}
 7	
 8	export function buildResults(args) {
 9	  return [
10	    buildInt8ul(args.a),
11	    buildInt16ul(args.b),
12	    buildInt8ul(args.c),
13	    buildBytes(getPythonLength(args.d), encodeUtf8(args.d)),
14	    buildInt8ul(args.f),
15	    buildInt8ul(args.g),
16	    buildInt8ul(args.i),
17	    buildBytes(getPythonLength(args.h), encodeUtf8(args.h)),
18	    buildInt8ul((args.a + args.b + args.c) % 256n),
19	  ];
20	}
21	
22	export function buildInt8ul(value) {
23	  assertRange(value, 0n, 255n, 'FormatFieldError', "<B");
24	  const buffer = Buffer.alloc(1);
25	  buffer.writeUInt8(Number(value), 0);
26	  return buffer;
27	}
28	
29	export function buildInt16ul(value) {
30	  assertRange(value, 0n, 65535n, 'FormatFieldError', "<H");
31	  const buffer = Buffer.alloc(2);
32	  buffer.writeUInt16LE(Number(value), 0);
33	  return buffer;
34	}
35	
36	export function buildBytes(expectedLength, buffer) {
37	  if (buffer.length !== expectedLength) {
38	    throw new ConstructBuildError(
39	      `construct.core.StreamError: Error in path (building)\nbytes object of wrong length, expected ${expectedLength}, found ${buffer.length}`,
40	    );
41	  }
42	
43	  return buffer;
44	}
45	
46	export function isConstructBuildError(error) {
47	  return error instanceof ConstructBuildError;
48	}
49	
50	function encodeUtf8(value) {
51	  return Buffer.from(value, 'utf8');
52	}
53	
54	function getPythonLength(value) {
55	  return Array.from(value).length;
56	}
57	
58	function assertRange(value, minimum, maximum, errorName, formatCode) {
59	  if (value < minimum || value > maximum) {
60	    throw new ConstructBuildError(
61	      `construct.core.${errorName}: Error in path (building)\nstruct '${formatCode}' error during building, given value ${value.toString()}`,
62	    );
63	  }
64	}

 1	const ESCAPES = Object.freeze({
 2	  9: '\\t',
 3	  10: '\\n',
 4	  13: '\\r',
 5	  39: "\\'",
 6	  92: '\\\\',
 7	});
 8	
 9	export function formatPythonBytes(buffer) {
10	  let body = '';
11	
12	  for (const byte of buffer.values()) {
13	    if (byte in ESCAPES) {
14	      body += ESCAPES[byte];
15	      continue;
16	    }
17	
18	    if (byte >= 32 && byte <= 126) {
19	      body += String.fromCharCode(byte);
20	      continue;
21	    }
22	
23	    body += `\\x${byte.toString(16).padStart(2, '0')}`;
24	  }
25	
26	  return `b'${body}'`;
27	}
28	
29	export function renderPythonBytesLines(buffers) {
30	  return `${buffers.map((buffer) => formatPythonBytes(buffer)).join('\n')}\n`;
31	}

 1	import {
 2	  CliExit,
 3	  buildResults,
 4	  getProgramName,
 5	  isConstructBuildError,
 6	  parseCommandLine,
 7	  renderPythonBytesLines,
 8	} from './lib/index.mjs';
 9	
10	function main(argv = process.argv.slice(2)) {
11	  const programName = getProgramName(process.argv[1]);
12	  const args = parseCommandLine(argv, programName);
13	  const results = buildResults(args);
14	  process.stdout.write(renderPythonBytesLines(results));
15	}
16	
17	try {
18	  main();
19	} catch (error) {
20	  if (error instanceof CliExit) {
21	    const stream = error.streamName === 'stdout' ? process.stdout : process.stderr;
22	    stream.write(error.message);
23	    process.exit(error.code);
24	  }
25	
26	  if (isConstructBuildError(error)) {
27	    process.stderr.write(`${error.message}\n`);
28	    process.exit(1);
29	  }
30	
31	  throw error;
32	}
